package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "loan")
public class LoanJpaEntity {

    private static final String REASON_CODE_DELIMITER = ",";

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    private LocalDate returnedAt;

    @Column(nullable = false)
    private boolean creditApproved;

    @Column(nullable = false)
    private int creditScore;

    @Column(nullable = false, length = 1000)
    private String creditReasonCodes;

    @Column(nullable = false)
    private Instant creditCheckedAt;

    private String creditProviderName;

    private String creditProviderVersion;

    protected LoanJpaEntity() {
    }

    private LoanJpaEntity(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
                          boolean creditApproved, int creditScore, String creditReasonCodes, Instant creditCheckedAt,
                          String creditProviderName, String creditProviderVersion) {
        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.loanedAt = loanedAt;
        this.dueAt = dueAt;
        this.returnedAt = returnedAt;
        this.creditApproved = creditApproved;
        this.creditScore = creditScore;
        this.creditReasonCodes = creditReasonCodes;
        this.creditCheckedAt = creditCheckedAt;
        this.creditProviderName = creditProviderName;
        this.creditProviderVersion = creditProviderVersion;
    }

    static LoanJpaEntity from(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(REASON_CODE_DELIMITER, creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    Loan toDomain() {
        CreditCheck creditCheck = new CreditCheck(creditApproved, creditScore, splitReasonCodes(creditReasonCodes),
                creditCheckedAt, creditProviderName, creditProviderVersion);
        return Loan.reconstitute(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    }

    private static List<String> splitReasonCodes(String reasonCodes) {
        if (reasonCodes == null || reasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(reasonCodes.split(REASON_CODE_DELIMITER));
    }
}
package com.example.lending.adapter.out.persistence;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;

import java.util.List;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    Page<LoanJpaEntity> findByMemberIdAndReturnedAtIsNull(UUID memberId, Pageable pageable);

    List<LoanJpaEntity> findByMemberIdOrderByLoanedAtDescIdDesc(UUID memberId);
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.DeleteReservationPort;
import com.example.lending.application.port.out.LoadReservationPort;
import com.example.lending.application.port.out.SaveReservationPort;
import com.example.lending.domain.Reservation;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class ReservationPersistenceAdapter implements LoadReservationPort, SaveReservationPort, DeleteReservationPort {

    private final ReservationJpaRepository reservationJpaRepository;

    public ReservationPersistenceAdapter(ReservationJpaRepository reservationJpaRepository) {
        this.reservationJpaRepository = reservationJpaRepository;
    }

    @Override
    public List<Reservation> loadReservationsByBookId(UUID bookId) {
        return reservationJpaRepository.findByBookIdOrderBySeqAsc(bookId).stream()
                .map(ReservationJpaEntity::toDomain)
                .toList();
    }

    @Override
    public void saveReservation(Reservation reservation) {
        reservationJpaRepository.save(ReservationJpaEntity.from(reservation));
    }

    @Override
    public void deleteReservation(UUID reservationId) {
        reservationJpaRepository.deleteByReservationId(reservationId);
    }
}
package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetMemberLoansUseCase;
import com.example.lending.application.port.in.GetMemberLoansUseCase.GetMemberLoansQuery;
import com.example.lending.application.port.in.GetMemberUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase.RegisterMemberCommand;
import com.example.lending.application.port.in.SuspendMemberUseCase;
import com.example.lending.application.port.in.UnsuspendMemberUseCase;
import com.example.lending.domain.Member;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final GetMemberLoansUseCase getMemberLoansUseCase;
    private final SuspendMemberUseCase suspendMemberUseCase;
    private final UnsuspendMemberUseCase unsuspendMemberUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            GetMemberLoansUseCase getMemberLoansUseCase, SuspendMemberUseCase suspendMemberUseCase,
                            UnsuspendMemberUseCase unsuspendMemberUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.getMemberLoansUseCase = getMemberLoansUseCase;
        this.suspendMemberUseCase = suspendMemberUseCase;
        this.unsuspendMemberUseCase = unsuspendMemberUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        Member member = registerMemberUseCase.registerMember(new RegisterMemberCommand(request.memberId(), request.name()));
        return MemberResponse.from(member);
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    @PostMapping("/{memberId}/suspend")
    public MemberResponse suspendMember(@PathVariable UUID memberId) {
        return MemberResponse.from(suspendMemberUseCase.suspendMember(memberId));
    }

    @PostMapping("/{memberId}/unsuspend")
    public MemberResponse unsuspendMember(@PathVariable UUID memberId) {
        return MemberResponse.from(unsuspendMemberUseCase.unsuspendMember(memberId));
    }

    @GetMapping("/{memberId}/loans")
