import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.UUID;

@Entity
@Table(name = "reservation")
public class ReservationJpaEntity {

    // 삽입 순서를 줄 순서로 쓴다. 같은 밀리초에 들어온 예약도 순서가 섞이지 않도록 DB 채번 값을 쓴다.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long seq;

    @Column(nullable = false, unique = true)
    private UUID reservationId;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    protected ReservationJpaEntity() {
    }

    private ReservationJpaEntity(UUID reservationId, UUID bookId, UUID memberId) {
        this.reservationId = reservationId;
        this.bookId = bookId;
        this.memberId = memberId;
    }

    static ReservationJpaEntity from(Reservation reservation) {
        return new ReservationJpaEntity(reservation.getId(), reservation.getBookId(), reservation.getMemberId());
    }

    Reservation toDomain() {
        return Reservation.reconstitute(reservationId, bookId, memberId);
    }
}

