import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void registering_a_member_returns_201_with_member_id() throws Exception {
        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").isString())
                .andExpect(jsonPath("$.name").value("김민지"));
    }

    @Test
    void registering_a_member_with_given_member_id_returns_201_with_that_id() throws Exception {
        String memberId = UUID.randomUUID().toString();

        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + memberId + "\",\"name\":\"후원자\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.name").value("후원자"));
    }

    @Test
    void registering_a_member_with_existing_member_id_returns_409() throws Exception {
        String memberId = UUID.randomUUID().toString();
        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + memberId + "\",\"name\":\"김민지\"}"))
                .andExpect(status().isCreated());

        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + memberId + "\",\"name\":\"다른이름\"}"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_ALREADY_EXISTS"));
    }

    @Test
    void registering_a_member_with_blank_name_returns_400() throws Exception {
        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"   \"}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void registering_a_member_without_name_returns_400() throws Exception {
        mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void getting_a_registered_member_returns_200() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode member = objectMapper.readTree(registered);
        String memberId = member.get("memberId").asText();

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.name").value("김민지"));
    }

    @Test
    void getting_an_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void new_member_is_not_suspended() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
    }

    @Test
    void suspending_a_member_returns_200_and_marks_member_as_suspended() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(true));

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(true));
    }

    @Test
    void unsuspending_a_member_returns_200_and_clears_suspension() throws Exception {
        String memberId = registerMember();
        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());

        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
    }

    @Test
    void suspending_or_unsuspending_an_unknown_member_returns_404() throws Exception {
        mockMvc.perform(post("/members/{memberId}/suspend", UUID.randomUUID()))
                .andExpect(status().isNotFound());
        mockMvc.perform(post("/members/{memberId}/unsuspend", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }
}
