package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class AuditLogIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_and_returning_a_book_records_both_actions_on_the_loan_in_order() throws Exception {
        String memberId = registerMember();
        String loanId = loanBook(registerBook(), memberId);
        mockMvc.perform(post("/loans/" + loanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].action").value("LOAN"))
                .andExpect(jsonPath("$[0].targetId").value(loanId))
                .andExpect(jsonPath("$[0].memberId").value(memberId))
                .andExpect(jsonPath("$[0].occurredAt").isString())
                .andExpect(jsonPath("$[1].action").value("RETURN"))
                .andExpect(jsonPath("$[1].targetId").value(loanId))
                .andExpect(jsonPath("$[1].memberId").value(memberId));
    }

    @Test
    void discarding_a_book_records_discard_on_the_book_with_null_member() throws Exception {
        String bookId = registerBook();
        mockMvc.perform(post("/books/" + bookId + "/discard")).andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].action").value("DISCARD"))
                .andExpect(jsonPath("$[0].targetId").value(bookId))
                .andExpect(jsonPath("$[0].memberId").isEmpty());
    }

    @Test
    void suspending_and_unsuspending_a_member_records_both_actions_on_the_member() throws Exception {
        String memberId = registerMember();
        mockMvc.perform(post("/members/" + memberId + "/suspend")).andExpect(status().isOk());
        mockMvc.perform(post("/members/" + memberId + "/unsuspend")).andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].action").value("SUSPEND"))
                .andExpect(jsonPath("$[0].memberId").isEmpty())
                .andExpect(jsonPath("$[1].action").value("UNSUSPEND"))
                .andExpect(jsonPath("$[1].memberId").isEmpty());
    }

    @Test
    void rejected_loan_records_nothing() throws Exception {
        String bookId = registerBook();
        String memberId = registerMember();
        mockMvc.perform(post("/members/" + memberId + "/suspend")).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, memberId)))
                .andExpect(status().isConflict());

        mockMvc.perform(get("/audit").param("targetId", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void unknown_target_returns_empty_list() throws Exception {
        mockMvc.perform(get("/audit").param("targetId", UUID.randomUUID().toString()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId));
    }
}

